        // Optimised for small numbers.
        // Better still would be __builtin_clz on hi/lo 32 and get the
        // starting point very rapidly.
        if (d<.0001)
                i+=0;
        else if (d<0.001)
                i+=5;
        else if (d < 0.01)
                i+=50;
        else if (d < 0.1)
                i+=500;
        else if (d < 1)
                i+=5000;
        else if (d < 10)
                i+=50000;
        else if (d < 100)
                i+=500000;
        else if (d < 1000)
                i+=5000000;
        else if (d < 10000)
                i+=50000000;
        else if (d < 100000)
                i+=500000000;
        else
